function pstr(string $key, int $max=500): string { return mb_substr(trim((string)($_POST[$key] ?? '')), 0, $max); }
function retain_voucher_form(): void {
    $_SESSION['_voucher_form'] = [
        'id'=>(int)($_POST['id']??0),'voucher_date'=>pstr('voucher_date',10),'type'=>pstr('type',30),'description'=>pstr('description',500),
