    ];
}
function hrow(array $cells): string { return '<tr>' . implode('', array_map(fn($v)=>'<td>'.$v.'</td>', $cells)) . '</tr>'; }
function select_options(array $items, mixed $selected, callable $label): string { $s=''; foreach($items as $item){$v=(string)$item['id'];$s.='<option value="'.e($v).'"'.((string)$selected===$v?' selected':'').'>'.e($label($item)).'</option>';} return $s; }
function voucher_row(array $v): string {
    $sum=(float)$v['debits'];
    return hrow(['<a href="'.url('voucher',['id'=>$v['id']]).'"><strong>'.e($v['voucher_no']).'</strong></a>',e($v['voucher_date']),e($v['description']),e(status_label($v['status'])),money($sum)]);
}
function get_voucher(int $id, bool $lock=false): array {
    $q=db()->prepare('SELECT v.*,uc.display_name creator_name,ua.display_name approver_name,up.display_name poster_name FROM vouchers v LEFT JOIN users uc ON uc.id=v.created_by LEFT JOIN users ua ON ua.id=v.approved_by LEFT JOIN users up ON up.id=v.posted_by WHERE v.id=?'.($lock?' FOR UPDATE':'')); $q->execute([$id]); $v=$q->fetch(); if(!$v) throw new RuntimeException('找不到這張傳票。');
    $q=db()->prepare('SELECT l.*,a.code,a.name FROM voucher_lines l JOIN accounts a ON a.id=l.account_id WHERE l.voucher_id=? ORDER BY l.line_no'); $q->execute([$id]); $v['lines']=$q->fetchAll(); return $v;
}
function check_open_period(string $date): void { $q=db()->prepare("SELECT id FROM accounting_periods WHERE status='open' AND start_date<=? AND end_date>=?"); $q->execute([$date,$date]); if(!$q->fetch()) throw new RuntimeException('傳票日期不在任何已開放的會計期間內。'); }

